import{_ as t,c as r,o,a5 as i}from"./chunks/framework.DuCYAsAJ.js";const h=JSON.parse('{"title":"单元测试与集成测试","description":"","frontmatter":{"title":"单元测试与集成测试","source":"https://app.devin.ai/org/feed/wiki/qiqi776/zfeed?branch=main#10.1","branch":"main","level":1,"order":10.1,"date":"2026-05-24T00:00:00.000Z"},"headers":[],"relativePath":"posts/projects/zfeed/10-testing-and-benchmarking/01-unit-and-integration-testing.md","filePath":"posts/projects/zfeed/10-testing-and-benchmarking/01-unit-and-integration-testing.md","lastUpdated":1779632679000}'),a={name:"posts/projects/zfeed/10-testing-and-benchmarking/01-unit-and-integration-testing.md"};function c(n,e,l,s,p,g){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="单元测试与集成测试" tabindex="-1">单元测试与集成测试 <a class="header-anchor" href="#单元测试与集成测试" aria-label="Permalink to &quot;单元测试与集成测试&quot;">​</a></h1><details><summary>相关源文件</summary><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/config/config_env_test.go" target="_blank" rel="noreferrer">app/front/internal/config/config_env_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/config/config_env_test.go" target="_blank" rel="noreferrer">app/rpc/content/internal/config/config_env_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/contentservice_test.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/contentservice_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/deletecontentlogic.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/deletecontentlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/recommendfeedlogic.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/recommendfeedlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/recommendfeedlogic_test.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/recommendfeedlogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/config/config_env_test.go" target="_blank" rel="noreferrer">app/rpc/count/internal/config/config_env_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/config/config_env_test.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/config/config_env_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/mq/consumer/like_consumer_test.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/mq/consumer/like_consumer_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/repositories/like_repository.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/repositories/like_repository.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/repositories/like_repository_test.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/repositories/like_repository_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchcontentslogic.go" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchcontentslogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchlogic_test.go" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchlogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchuserslogic.go" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchuserslogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/config/config_env_test.go" target="_blank" rel="noreferrer">app/rpc/user/internal/config/config_env_test.go</a></li></ul></details><p>zfeed 的测试策略强调使用内存基础设施和专用工具实现高保真隔离，以保证数据库 schema 约束、缓存正确性和消息处理幂等性。单元测试主要验证 <code>logic</code> 包中的业务逻辑，集成测试则覆盖仓储层、缓存和数据库层之间的交互。</p><h2 id="测试基础设施与工具" tabindex="-1">测试基础设施与工具 <a class="header-anchor" href="#测试基础设施与工具" aria-label="Permalink to &quot;测试基础设施与工具&quot;">​</a></h2><p>为了在不依赖真实 Docker 栈的情况下提供接近真实的测试环境，zfeed 使用了多种基础设施内存替代方案。</p><h3 id="内存基础设施-provider" tabindex="-1">内存基础设施 Provider <a class="header-anchor" href="#内存基础设施-provider" aria-label="Permalink to &quot;内存基础设施 Provider&quot;">​</a></h3><ul><li>Redis：使用 <code>miniredis</code> 模拟，它提供真实 Redis 兼容的 TCP server。测试通过 <code>gzredis.MustNewRedis</code> 将其集成进来 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchlogic_test.go#L87-L95" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchlogic_test.go#87-95</a></li><li>MySQL：使用 SQLite 内存模式和 <code>cache=shared</code> 模拟。为了弥合 SQLite 与 MySQL 语法差异，测试使用 GORM 的 <code>AutoMigrate</code> 根据实体定义生成 schema <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchlogic_test.go#L74-L85" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchlogic_test.go#74-85</a></li><li>gRPC 依赖：下游 RPC 服务会替换为 Stub 实现，例如 <code>stubSearchFollowService</code>，以便针对特定测试用例注入自定义行为 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchlogic_test.go#L126-L152" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchlogic_test.go#126-152</a></li></ul><h3 id="mysqltest-工具" tabindex="-1">mysqltest 工具 <a class="header-anchor" href="#mysqltest-工具" aria-label="Permalink to &quot;mysqltest 工具&quot;">​</a></h3><p>对于需要真实 MySQL 特性的服务，例如 <code>ON DUPLICATE KEY UPDATE</code> 或特定索引行为，会使用 <code>mysqltest</code> 工具。该工具管理到专用测试数据库的连接，通常位于 <code>33306</code> 端口，并提供辅助函数来维护 schema 状态。</p><table tabindex="0"><thead><tr><th>函数</th><th>职责</th></tr></thead><tbody><tr><td><code>Open()</code></td><td>初始化到测试 MySQL 实例的 GORM 连接 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go#L29-L53" target="_blank" rel="noreferrer">app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go#29-53</a></td></tr><tr><td><code>EnsureLikeTables()</code></td><td>为 <code>zfeed_like</code>、<code>zfeed_mq_consume_dedup</code> 和 outbox 表执行 DDL <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go#L68-L174" target="_blank" rel="noreferrer">app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go#68-174</a></td></tr><tr><td><code>CleanupLikeRowsByRange()</code></td><td>删除特定 ID 范围内的数据，以保证测试隔离 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go#L253-L270" target="_blank" rel="noreferrer">app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go#253-270</a></td></tr><tr><td><code>CleanupDedupRows()</code></td><td>清理 MQ consumer 测试中的幂等 token <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go#L272-L282" target="_blank" rel="noreferrer">app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go#272-282</a></td></tr></tbody></table><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchlogic_test.go#L74-L95" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchlogic_test.go#74-95</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go#L1-L174" target="_blank" rel="noreferrer">app/rpc/interaction/internal/testutil/mysqltest/mysqltest.go#1-174</a></p><hr><h2 id="logic-层测试模式" tabindex="-1">Logic 层测试模式 <a class="header-anchor" href="#logic-层测试模式" aria-label="Permalink to &quot;Logic 层测试模式&quot;">​</a></h2><p><code>logic</code> 包中的测试关注数据编排和外部服务调用。</p><h3 id="搜索与快照测试" tabindex="-1">搜索与快照测试 <a class="header-anchor" href="#搜索与快照测试" aria-label="Permalink to &quot;搜索与快照测试&quot;">​</a></h3><p><code>SearchUsersLogic</code> 和 <code>SearchContentsLogic</code> 的测试验证搜索结果是否能正确补全与请求用户相关的状态，例如 <code>IsFollowing</code>，同时验证基于 snapshot 的分页能跨请求稳定工作。</p><p>Search Logic 测试流程</p><ol><li>Seed：在 SQLite 中创建用户/内容 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchlogic_test.go#L156-L161" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchlogic_test.go#156-161</a></li><li>Mock：配置 <code>stubSearchFollowService</code> 返回特定关系状态 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchlogic_test.go#L166-L178" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchlogic_test.go#166-178</a></li><li>Execute：用 <code>ViewerId</code> 调用 <code>SearchUsers</code> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchlogic_test.go#L180-L184" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchlogic_test.go#180-184</a></li><li>Verify：断言响应中的 <code>IsFollowing</code> 字段与 mock 输出一致 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchlogic_test.go#L188-L193" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchlogic_test.go#188-193</a></li></ol><h3 id="内容详情与可见性" tabindex="-1">内容详情与可见性 <a class="header-anchor" href="#内容详情与可见性" aria-label="Permalink to &quot;内容详情与可见性&quot;">​</a></h3><p><code>GetContentDetail</code> 的集成测试通过检查 <code>ViewerId</code> 与内容 <code>author_id</code> 的关系，确保隐私规则（Private vs. Public）被正确执行。</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchlogic_test.go#L154-L194" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchlogic_test.go#154-194</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/contentservice_test.go#L158-L196" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/contentservice_test.go#158-196</a></p><hr><h2 id="仓储层与幂等性测试" tabindex="-1">仓储层与幂等性测试 <a class="header-anchor" href="#仓储层与幂等性测试" aria-label="Permalink to &quot;仓储层与幂等性测试&quot;">​</a></h2><p><code>interaction-rpc</code> 服务高度依赖 Transactional Outbox 和幂等 Upsert 模式。测试这些能力需要验证特定数据库状态转换。</p><h3 id="like-repository-集成" tabindex="-1">Like Repository 集成 <a class="header-anchor" href="#like-repository-集成" aria-label="Permalink to &quot;Like Repository 集成&quot;">​</a></h3><p><code>LikeRepository.Upsert</code> 实现使用复杂的 <code>ON DUPLICATE KEY UPDATE</code> 查询，并通过 <code>GREATEST(last_event_ts, VALUES(last_event_ts))</code> 处理乱序事件 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/repositories/like_repository.go#L46-L79" target="_blank" rel="noreferrer">app/rpc/interaction/internal/repositories/like_repository.go#46-79</a></p><p>Like Upsert 的测试用例：</p><ul><li>Newer Wins：时间戳更高的事件会覆盖现有状态 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/repositories/like_repository_test.go#L27-L72" target="_blank" rel="noreferrer">app/rpc/interaction/internal/repositories/like_repository_test.go#27-72</a></li><li>Older Ignored：时间戳更低的事件不会改变记录，即使 status 不同 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/repositories/like_repository_test.go#L74-L122" target="_blank" rel="noreferrer">app/rpc/interaction/internal/repositories/like_repository_test.go#74-122</a></li></ul><h3 id="consumer-幂等性" tabindex="-1">Consumer 幂等性 <a class="header-anchor" href="#consumer-幂等性" aria-label="Permalink to &quot;Consumer 幂等性&quot;">​</a></h3><p><code>LikeConsumer</code> 测试验证针对重复消息的双层保护：</p><ol><li>应用层：检查 <code>zfeed_mq_consume_dedup</code> 表 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/mq/consumer/like_consumer_test.go#L29-L62" target="_blank" rel="noreferrer">app/rpc/interaction/internal/mq/consumer/like_consumer_test.go#29-62</a></li><li>数据库层：<code>Upsert</code> 逻辑处理过期时间戳 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/mq/consumer/like_consumer_test.go#L112-L161" target="_blank" rel="noreferrer">app/rpc/interaction/internal/mq/consumer/like_consumer_test.go#112-161</a></li></ol><h3 id="测试组件关系-interaction-服务" tabindex="-1">测试组件关系（Interaction 服务） <a class="header-anchor" href="#测试组件关系-interaction-服务" aria-label="Permalink to &quot;测试组件关系（Interaction 服务）&quot;">​</a></h3><p>下图展示测试实体如何与真实实现和 mock 基础设施交互。</p><p>标题：Interaction 测试架构</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/repositories/like_repository.go#L46-L79" target="_blank" rel="noreferrer">app/rpc/interaction/internal/repositories/like_repository.go#46-79</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/repositories/like_repository_test.go#L27-L122" target="_blank" rel="noreferrer">app/rpc/interaction/internal/repositories/like_repository_test.go#27-122</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/mq/consumer/like_consumer_test.go#L29-L161" target="_blank" rel="noreferrer">app/rpc/interaction/internal/mq/consumer/like_consumer_test.go#29-161</a></p><hr><h2 id="缓存隔离与并发模式" tabindex="-1">缓存隔离与并发模式 <a class="header-anchor" href="#缓存隔离与并发模式" aria-label="Permalink to &quot;缓存隔离与并发模式&quot;">​</a></h2><h3 id="redis-lua-脚本测试" tabindex="-1">Redis Lua 脚本测试 <a class="header-anchor" href="#redis-lua-脚本测试" aria-label="Permalink to &quot;Redis Lua 脚本测试&quot;">​</a></h3><p><code>RecommendFeedLogic</code> 使用复杂 Lua 脚本（<code>QueryHotFeedZSetScript</code>）在 Redis 中执行原子分页和 snapshot 选择 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/recommendfeedlogic.go#L133-L145" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/recommendfeedlogic.go#133-145</a>。单元测试会重点覆盖这些结果的解析器，确保缓存未命中、空 snapshot、无效 cursor 等边界情况都能被处理。</p><table tabindex="0"><thead><tr><th>测试用例</th><th>场景</th><th>验证逻辑</th></tr></thead><tbody><tr><td><code>TestParseHit</code></td><td>有效 Redis 响应</td><td>正确提取 <code>nextCursor</code>、<code>hasMore</code> 和 ID <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/recommendfeedlogic_test.go#L15-L47" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/recommendfeedlogic_test.go#15-47</a></td></tr><tr><td><code>TestParseMiss</code></td><td>Key 不存在</td><td>返回 <code>exists=false</code> 且不报错 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/recommendfeedlogic_test.go#L49-L76" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/recommendfeedlogic_test.go#49-76</a></td></tr><tr><td><code>TestColdStart</code></td><td>Redis 为空</td><td>返回空响应而不是失败 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/recommendfeedlogic_test.go#L128-L149" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/recommendfeedlogic_test.go#128-149</a></td></tr></tbody></table><h3 id="删除时的缓存清理" tabindex="-1">删除时的缓存清理 <a class="header-anchor" href="#删除时的缓存清理" aria-label="Permalink to &quot;删除时的缓存清理&quot;">​</a></h3><p><code>DeleteContentLogic</code> 包含复杂的 <code>cleanupIndexes</code> 流程，会使多个 Redis key 失效，包括 Follow Inbox、Favorite Feed 和 Hot Feed <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/deletecontentlogic.go#L108-L118" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/deletecontentlogic.go#108-118</a>。集成测试验证内容在 MySQL 中被软删除后，对应成员会从 Redis ZSet 中移除 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/deletecontentlogic.go#L188-L192" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/deletecontentlogic.go#188-192</a></p><h3 id="search-snapshot-流程" tabindex="-1">Search Snapshot 流程 <a class="header-anchor" href="#search-snapshot-流程" aria-label="Permalink to &quot;Search Snapshot 流程&quot;">​</a></h3><p>该图连接 Search Logic 代码与测试运行期间的基础设施状态。</p><p>标题：Search Snapshot 集成流程</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/feed/recommendfeedlogic_test.go#L15-L182" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/feed/recommendfeedlogic_test.go#15-182</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/deletecontentlogic.go#L108-L192" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/deletecontentlogic.go#108-192</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/searchcontentslogic.go#L159-L221" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/searchcontentslogic.go#159-221</a></p>',46)])])}const b=t(a,[["render",c]]);export{h as __pageData,b as default};
